def reference_fix_spaces(text):
    res = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] != ' ':
            res.append(text[i])
            i += 1
        else:
            j = i
            while j < n and text[j] == ' ':
                j += 1
            run = j - i
            if run == 1:
                res.append('_')
            elif run == 2:
                res.append('__')
            else:
                res.append('-')
            i = j
    return ''.join(res)


def test_quad_space_becomes_single_dash():
    assert fix_spaces("    ") == "-"
